{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer korrekt, at arbejdsophør ikke i sig selv giver ret. Men det siger, at SU-handicaptillæg afgøres af SU-myndigheden under Uddannelses- og Forskningsstyrelsen, ikke Udbetaling Danmark. Det strider mod SU-bekendtgørelsen § 36, stk. 1, og vejledningen, hvor Udbetaling Danmark vurderer. Det er en væsentlig juridisk fejl og besvarer 'hvad vurderer Udbetaling Danmark' forkert."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det siger ikke, at ansøgerens mulighed for andre typer arbejde vurderes ud fra sagens øvrige oplysninger. Skånehensyn eller mindre omfang er kun antydet svagt ('hvilke opgaver og timetal ansøgeren kunne klare'), ikke som vurdering af andre arbejdstyper med skånehensyn. De kritiske elementer er derfor ikke dækket."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret adresserer 'i sig selv'-delen. Den anden del, hvad Udbetaling Danmark vurderer, besvares ikke korrekt. Svaret flytter vurderingen til en anden myndighed og beskriver ikke den vurdering, vejledningen angiver."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en myndighed, 'SU-myndigheden under Uddannelses- og Forskningsstyrelsen', uden støtte i materialet. Materialet peger på Udbetaling Danmark. Svaret tilføjer desuden, at ansøgeren 'reelt næsten ikke kan have et erhvervsarbejde'. Det er en parafrase af lovens 'meget betydelige begrænsninger' og har delvis støtte, men myndighedspåstanden er alene afgørende."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at ophøret ikke i sig selv afgør retten, og at der foretages en samlet konkret vurdering. Det udelader den vigtige pointe, at vurderingen går på muligheden for andre jobtyper med skånehensyn eller i mindre omfang. Eksemplet med arbejde uden fysisk belastning er udeladt, hvilket er acceptabelt. Den manglende vurdering af andre arbejdstyper betyder, at de krævede forbehold ikke er fuldt bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Det interne ræsonnement hænger sammen: Ophør er ikke tilstrækkeligt, varig og omfattende nedsættelse af arbejdsevnen er afgørende, og oplysninger indgår i en konkret vurdering. Konklusionen følger af disse trin. Fejlen om myndigheden er et separat udsagn og skaber ikke intern modsigelse i ræsonnementet."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret siger, at tillægget 'normalt' afgøres af SU-myndigheden, ikke Udbetaling Danmark. Det forvrænger kilden, hvor Udbetaling Danmark er beslutningstager. Svaret udtrykker i øvrigt 'kan indgå' og 'kan være relevant' passende."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler arbejdsophør på grund af funktionsnedsættelse og siger, at det ikke i sig selv giver ret og kræver en konkret vurdering. Det nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen, og angiver forkert myndighed."
    },
    "A23": {
      "label": "no",
      "reason": "Svaret siger ikke, at der vurderes, om ansøgeren kan klare andre typer arbejde, eventuelt med skånehensyn. Det nævner kun arbejdsevne, timetal og opgaver i generel form, og tilskriver vurderingen en forkert myndighed."
    }
  },
  "overall_notes": "Svaret har den korrekte hovedkonklusion om, at arbejdsophør ikke i sig selv giver ret til tillægget. Det mangler den centrale vurdering af arbejdets karakter og muligheden for andre arbejdstyper med skånehensyn eller mindre omfang. Det fejlplacerer desuden afgørelseskompetencen hos SU-myndigheden i stedet for Udbetaling Danmark. Der er ingen kildeangivelse, så C04 er not_met, og C05 og C06 er not_assessable."
}

